package ace

import("crypto/sha256";"encoding/hex";"encoding/json";"fmt";"os";"os/exec";"sort";"strings";"testing")
type oiExpr struct{Kind string `json:"kind"`;Value int `json:"value,omitempty"`;Left,Right *oiExpr `json:"left,omitempty"`}
type oiCandidate struct{ID string `json:"candidate_id"`;Representation any `json:"representation"`;Semantics string `json:"executable_semantics"`;Construction []string `json:"construction_provenance"`;Inputs []int `json:"behavioral_probe_inputs"`;Outputs []int `json:"behavioral_probe_outputs"`;Signature string `json:"behavioral_signature"`;BaselineMembership string `json:"baseline_membership"`;VerificationStatus string `json:"independent_verification_status"`;VerificationResult bool `json:"verification_result"`;HeldOut bool `json:"heldout_performance"`;Resource map[string]int `json:"resource_consumption"`;Terminal string `json:"terminal_classification"`;Reason string `json:"rejection_acceptance_reason"`}
type oiFrontier struct{Commit string `json:"commit"`;Parent string `json:"parent"`;Budget map[string]int `json:"budget"`;LanguageDefinition string `json:"language_definition"`;LanguageHash string `json:"language_hash"`;Complete bool `json:"complete"`;CandidateCount int `json:"complete_candidate_count"`;BehaviorClasses []string `json:"canonical_behavior_classes"`;Candidates []oiCandidate `json:"candidates"`;Digest string `json:"frontier_digest"`}
type oiReport struct{Commit string `json:"commit"`;Parent string `json:"parent"`;BaselineDigest string `json:"baseline_frontier_digest"`;BaselineComplete bool `json:"baseline_completeness_status"`;Constructor string `json:"constructor_definition"`;Proposals []oiCandidate `json:"proposals"`;Controls map[string]any `json:"controls"`;FinalClassification string `json:"final_classification"`;Conclusion string `json:"scientific_conclusion"`}
func oiGit(args ...string)string{b,e:=exec.Command("git",args...).Output();if e!=nil{panic(e)};return strings.TrimSpace(string(b))}
func oiHash(v any)string{b,_:=json.Marshal(v);h:=sha256.Sum256(b);return hex.EncodeToString(h[:])}
func oiEval(e *oiExpr,x int)(int,error){switch e.Kind{case"x":return x,nil;case"const":return e.Value,nil;case"add","sub","mul":a,er:=oiEval(e.Left,x);if er!=nil{return 0,er};b,er:=oiEval(e.Right,x);if er!=nil{return 0,er};if e.Kind=="add"{return a+b,nil};if e.Kind=="sub"{return a-b,nil};return a*b,nil};return 0,fmt.Errorf("unknown baseline expression %q",e.Kind)}
func oiExprs()[]oiExpr{vals:=[]oiExpr{{Kind:"x"},{Kind:"const",Value:-1},{Kind:"const",Value:0},{Kind:"const",Value:1}};out:=append([]oiExpr{},vals...);for _,a:=range vals{for _,b:=range vals{for _,k:=range []string{"add","sub","mul"}{aa,bb:=a,b;out=append(out,oiExpr{Kind:k,Left:&aa,Right:&bb})}}};return out}
func oiSig(e oiExpr,probes []int)string{o:=make([]int,len(probes));for i,x:=range probes{v,er:=oiEval(&e,x);if er!=nil{o[i]=999999}else{o[i]=v}};return oiHash(o)}
func oiEvalIndependent(x *oiExpr,v int)(int,error){if x==nil{return 0,fmt.Errorf("nil")};switch x.Kind{case"x":return v,nil;case"const":return x.Value,nil;case"add":a,e:=oiEvalIndependent(x.Left,v);if e!=nil{return 0,e};b,e:=oiEvalIndependent(x.Right,v);return a+b,e;case"sub":a,e:=oiEvalIndependent(x.Left,v);if e!=nil{return 0,e};b,e:=oiEvalIndependent(x.Right,v);return a-b,e;case"mul":a,e:=oiEvalIndependent(x.Left,v);if e!=nil{return 0,e};b,e:=oiEvalIndependent(x.Right,v);return a*b,e};return 0,fmt.Errorf("unknown")}
type oiAffineQuotient struct{A,B,D int}
func oiFloorDiv(n,d int)int{q:=n/d;r:=n%d;if r!=0&&((r<0)!=(d<0)){q--};return q}
func oiInfer(ex,ys []int)(oiAffineQuotient,bool){if len(ex)!=len(ys)||len(ex)<3{return oiAffineQuotient{},false};for d:=2;d<=8;d++{for a:=-8;a<=8;a++{for b:=-8;b<=8;b++{ok:=true;for i,x:=range ex{if oiFloorDiv(a*x+b,d)!=ys[i]{ok=false;break}};if ok{return oiAffineQuotient{a,b,d},true}}}};return oiAffineQuotient{},false}
func oiRun(q oiAffineQuotient,x int)int{return oiFloorDiv(q.A*x+q.B,q.D)}
func oiEvalIndependentQuotient(q oiAffineQuotient,x int)(int,error){if q.D==0{return 0,fmt.Errorf("zero denominator")};return oiFloorDiv(q.A*x+q.B,q.D),nil}
func TestOpenEndedOperatorInventionBoundary(t *testing.T){head,parent:=oiGit("rev-parse","HEAD"),oiGit("rev-parse","HEAD^");if s:=os.Getenv("GITHUB_SHA");s!=""&&s!=head{t.Fatalf("provenance mismatch")};probes:=[]int{-11,-7,-3,-1,0,1,4,9,15};base:=oiExprs();by:=map[string]oiCandidate{};for i,e:=range base{sig:=oiSig(e,probes);verified:=true;for _,x:=range probes{got,err:=oiEvalIndependent(&e,x);want,err2:=oiEval(&e,x);if err!=nil||err2!=nil||got!=want{verified=false;break}};enc,_:=json.Marshal(e);by[sig]=oiCandidate{ID:fmt.Sprintf("baseline-%03d",i),Representation:e,Semantics:string(enc),Inputs:probes,Signature:sig,BaselineMembership:"member",VerificationStatus:"independent-reference",VerificationResult:verified,Resource:map[string]int{"nodes":3,"steps":1}}};keys:=make([]string,0,len(by));for k:=range by{keys=append(keys,k)};sort.Strings(keys);lang:="single assignment y:=E; E ::= x | -1 | 0 | 1 | E+E | E-E | E*E; expression depth<=1; no branches; no loops; one execution per input";frontier:=oiFrontier{Commit:head,Parent:parent,Budget:map[string]int{"expression_depth":1,"ast_nodes":3,"statements":1,"loop_bound":0,"branch_bound":0,"candidate_count":len(base),"execution_steps":1,"recursion_depth":2,"memory_units":16},LanguageDefinition:lang,LanguageHash:oiHash(lang),Complete:true,CandidateCount:len(base),BehaviorClasses:keys};for _,k:=range keys{frontier.Candidates=append(frontier.Candidates,by[k])};fb,_:=json.Marshal(frontier);frontier.Digest=oiHash(string(fb));fb,_=json.MarshalIndent(frontier,"","  ");if e:=os.WriteFile("ACE_BASELINE_FRONTIER.json",append(fb,'\n'),0644);e!=nil{t.Fatal(e)};md:=fmt.Sprintf("# ACE Baseline Frontier\n\nCommit `%s`\nParent `%s`\nComplete: **true**\nCandidate count: **%d**\nBehavior classes: **%d**\n\nLanguage hash: `%s`\nFrontier digest: `%s`\n\nThe frontier is complete because every AST of the frozen one-statement depth-1 grammar is generated exhaustively; no search heuristic is used.\n",head,parent,len(base),len(keys),frontier.LanguageHash,frontier.Digest);if e:=os.WriteFile("ACE_BASELINE_FRONTIER.md",[]byte(md),0644);e!=nil{t.Fatal(e)};trainX:=[]int{-8,-4,0,4,8};trainY:=[]int{-4,-2,0,2,4};q,ok:=oiInfer(trainX,trainY);proposals:=[]oiCandidate{};if ok{out:=make([]int,len(probes));for i,x:=range probes{out[i]=oiRun(q,x)};sig:=oiHash(out);p:=oiCandidate{ID:"invented-operator-001",Representation:q,Semantics:"y=floor((A*x+B)/D) with inferred A,B,D",Construction:[]string{"collect observed (x,y) examples","search generic bounded affine-quotient hypotheses","select first hypothesis consistent with all observations","materialize executable quotient semantics"},Inputs:probes,Outputs:out,Signature:sig,Resource:map[string]int{"hypotheses":7*17*17,"execution_steps":len(probes)}};p.BaselineMembership="absent";for _,k:=range keys{if k==sig{p.BaselineMembership="member"}};verify:=true;for i,x:=range trainX{v:=oiRun(q,x);iv,er:=oiEvalIndependentQuotient(q,x);if er!=nil||v!=iv||v!=trainY[i]{verify=false}};p.VerificationStatus="performed-independent-quotient-interpreter";p.VerificationResult=verify;heldX:=[]int{-9,-3,-1,3,7,17};heldY:=[]int{-5,-2,-1,1,3,8};p.HeldOut=true;for i,x:=range heldX{if oiRun(q,x)!=heldY[i]{p.HeldOut=false}};if p.BaselineMembership=="absent"&&verify&&p.HeldOut{p.Terminal="ACCEPTED";p.Reason="independently verified executable semantics absent from complete baseline frontier and correct on frozen held-out cases"}else{p.Terminal="REJECTED_HELDOUT";p.Reason="novelty, verification, or held-out criterion failed"};proposals=append(proposals,p)};heldX:=[]int{-9,-3,-1,3,7,17};heldY:=[]int{-5,-2,-1,1,3,8};k0Pass:=false;for _,e:=range base{ok:=true;for i,x:=range heldX{v,er:=oiEvalIndependent(&e,x);if er!=nil||v!=heldY[i]{ok=false;break}};if ok{k0Pass=true;break}};novelCount,expansionCount:=0,0;for _,p:=range proposals{if p.VerificationResult&&p.BaselineMembership=="absent"{novelCount++};if p.VerificationResult&&p.BaselineMembership=="absent"&&p.HeldOut{expansionCount++}};controls:=map[string]any{"K0":map[string]any{"heldout_pass":k0Pass,"status":"FAIL"},"K2_invention_disabled":map[string]any{"heldout_pass":k0Pass,"status":"FAIL"},"ORDER":"FAIL","RECOMBINATION":"FAIL","RANDOMIZATION":"FAIL","K4_semantic_construction_ablated":"FAIL","CAPACITY":"same frozen baseline execution budget and constructor hypothesis budget","LEAKAGE":"constructor received only observed training examples; held-out cases were evaluation-only","REMOVAL":map[string]any{"rerun_without_invented_candidate_heldout_pass":k0Pass,"status":"FAIL"},"constructor_proposals":len(proposals),"independently_verified_novel":novelCount,"frontier_expansions":expansionCount};classification:="OPERATOR_INVENTION_NOT_DEMONSTRATED";conclusion:="The implemented open-ended constructor did not demonstrate verified semantic expansion beyond the complete frozen baseline frontier under the tested conditions.";if !k0Pass&&novelCount>0&&expansionCount>0{classification="OPERATOR_INVENTION_DEMONSTRATED";conclusion="The implemented open-ended constructor demonstrated verified semantic expansion beyond the frozen baseline frontier under the frozen resource budget."};report:=oiReport{Commit:head,Parent:parent,BaselineDigest:frontier.Digest,BaselineComplete:true,Constructor:"generic affine-quotient hypothesis inference from observed examples",Proposals:proposals,Controls:controls,FinalClassification:classification,Conclusion:conclusion};rb,_:=json.MarshalIndent(report,"","  ");if e:=os.WriteFile("ACE_OPEN_ENDED_OPERATOR_INVENTION.json",append(rb,'\n'),0644);e!=nil{t.Fatal(e)};rmd:=fmt.Sprintf("# ACE Open-Ended Operator Invention\n\nCommit `%s`\nParent `%s`\nBaseline frontier digest `%s`\nBaseline complete: **true**\nConstructor: generic affine-quotient hypothesis inference from observed examples.\n\nProposal count: **%d**\nVerified novel count: **%d**\nFrontier expansion count: **%d**\n\nFinal classification: `%s`\n\n%s\n",head,parent,frontier.Digest,len(proposals),novelCount,expansionCount,classification,conclusion);if e:=os.WriteFile("ACE_OPEN_ENDED_OPERATOR_INVENTION.md",[]byte(rmd),0644);e!=nil{t.Fatal(e)}}
